-- Copy the live sponsor ads (src/data/sponsors.ts, 2 Nov 2026) into techtrendi.sponsors.

insert into techtrendi.sponsors (slug, active, show_on, sort_order, content)
select 'cyclopx-unlox', true, array['/', '/phones', '/tools/phone-comparison', '/tools/upgrade-calculator']::text[], 10, $seed${"name":"CyclopX Unlox","tagline":"Unlock Your World","cardText":"Phone and carrier unlocking for your own phone. Any brand, any network.","headline":"Unlock your phone. Use any network.","intro":"Stuck with a phone that only works on one network? CyclopX Unlox removes the network lock from your own phone, so it accepts the SIM card you choose. Any brand, any model, done with professional unlocking tools.","heroImage":"/sponsored/cyclopx-unlox-hero.jpg","heroImageAlt":"CyclopX Unlox — Unlock Your World. Phone, iPhone, Android and carrier unlock solutions.","highlights":["Any brand, any model","All major networks","Professional unlocking tools","Fast, secure, reliable"],"audience":{"title":"Got a phone from abroad?","text":"Many phones bought or sent from the US are locked to one American network, so a Ghana SIM won't work in them. Once the phone is unlocked, you can use your MTN, Telecel or AT SIM like any other phone."},"services":[{"title":"All phone unlocks","detail":"Any brand, any model","description":"Whatever phone you have, if it's locked to one network, CyclopX Unlox can unlock it so it works with SIM cards from other networks."},{"title":"iPhone network unlock","detail":"Use your iPhone on the network you choose","description":"iPhone stuck on one carrier? The network (carrier) lock is removed, so your iPhone accepts SIM cards from any network."},{"title":"Android unlocks","detail":"Samsung, Google, LG, Motorola and more","description":"Carrier-locked Samsung Galaxy, Google Pixel, LG, Motorola and other Android phones unlocked to work on other networks."},{"title":"Carrier unlock","detail":"AT&T, T-Mobile, Verizon, Xfinity, Boost, MetroPCS and all networks","description":"Phones locked to AT&T, T-Mobile, Verizon, Xfinity, Boost, MetroPCS, Cricket and other networks, unlocked so you can use them anywhere — including here in Ghana."}],"steps":[{"title":"Message on WhatsApp","detail":"Send your phone's brand and model, and the network it's locked to."},{"title":"Get your quote","detail":"You'll be told the price and how long it takes for your phone."},{"title":"Use any network","detail":"Once it's unlocked, put in the SIM card you want and you're connected."}],"reasons":[{"title":"Professional tools","detail":"Unlocks are done with paid, professional unlocking services."},{"title":"Any brand, any model","detail":"iPhone, Samsung, Google, LG, Motorola and more."},{"title":"Fast, secure, reliable","detail":"A professional service from start to finish."},{"title":"A real person to talk to","detail":"Ask your questions on WhatsApp before you pay anything."}],"faqs":[{"q":"What does unlocking a phone mean?","a":"A locked phone only works with SIM cards from the network that sold it. Unlocking removes that limit, so your phone accepts a SIM card from any network."},{"q":"Will an unlocked phone from the US work in Ghana?","a":"Yes. Once it's unlocked it can use MTN, Telecel or AT SIM cards. Most modern phones support Ghana's networks — if you're unsure about your model, ask on WhatsApp."},{"q":"How much does it cost and how long does it take?","a":"It depends on your phone model and the network it's locked to. Send those details on WhatsApp and you'll get a quote."},{"q":"What details do I need to send?","a":"Your phone's brand and model, the network it's locked to, and its IMEI number. To see the IMEI, dial *#06# on the phone."},{"q":"Can any phone be unlocked?","a":"This service is only for phones that you own. Lost or stolen phones are not unlocked."}],"promise":{"title":"Fast, secure, reliable","detail":"Professional service"},"phone":"233546616401","phoneDisplay":"+233 546 616 401","whatsappMessage":"Hi CyclopX Unlox, I saw your ad on TechTrendi. I'd like to unlock my phone.","socialHandle":"@CyclopXunlox","socialNetworks":"TikTok, Instagram and Facebook"}$seed$::jsonb
where not exists (select 1 from techtrendi.sponsors where slug = 'cyclopx-unlox');
